// Ambil semua field dari form (nama kolom dinamis)
const j = $json;
const skip = ['Timestamp', 'Waktu', 'Nomor'];

let isi = '';
for (const [k, v] of Object.entries(j)) {
  if (skip.some(s => k.toLowerCase().includes(s.toLowerCase()))) continue;
  isi += '*' + k + ':* ' + (v || '-') + '\n';
}

const nama = j['Nama'] || j['Nama Lengkap'] || j['Name'] || 'Pelanggan';

return [{
  json: {
    notif: '📩 *ORDER BARU DARI FORM*\n\nDari: ' + nama + '\n\n' + isi + '\nSegera ditindaklanjuti!',
    nama: nama,
    isi_lengkap: isi
  }
}];
